def find_minimal_edit(s_in, s_out):
    """Find the minimal edit operation that transforms s_in to s_out."""
    # Simple approach: find first difference and determine what needs to change
    if s_in == s_out:
        return None

    # Check if we're prepending
    if len(s_out) > len(s_in) and s_out[len(s_out)-len(s_in):] == s_in:
        return (s_in, s_out[:len(s_out)-len(s_in)], len(s_out)-len(s_in))

    # Check if we're appending  
    if len(s_out) > len(s_in) and s_out[:len(s_in)] == s_in:
        return (s_in, s_out[len(s_in):], 0)

    # For exact replacement, find first differing position
    for i in range(min(len(s_in), len(s_out))):
        if s_in[i] != s_out[i]:
            # Find the substring that needs to be replaced
            # We'll assume it's a simple replacement of a substring
            return (s_in[i:i+1], s_out[i:i+1], i)

    # If we get here, one string is prefix of the other
    if len(s_in) < len(s_out):
        # Append case
        return (s_in, s_out[len(s_in):], len(s_in))
    else:
        # Remove case
        return (s_in[len(s_out):], s_out, len(s_out))

# Test with our changed pairs
changed = [(0, 'fg', 'whfg'), (2, 'ukfx', 'hx')]
for idx, inp, outp in changed:
    edit = find_minimal_edit(inp, outp)
    print(f"Pair {idx}: '{inp}' -> '{outp}' | Edit: {edit}")

